#!/usr/bin/env python3
"""Integrate the complete exploratory extension into the journal manuscript.
Uses an immutable pre-extension content snapshot and saved numerical tables.
"""
import json,re,shutil
from pathlib import Path
import pandas as pd
from finalize_for_journal import write_markdown
R=Path(__file__).resolve().parents[1];O=R/'results';X=R/'extensions/strengthening_20261015'
for kind in ['manuscript','supplement']:
 p=O/(kind+'_pre_strengthening.json')
 if not p.exists():shutil.copy2(O/(kind+'_content.json'),p)
main=json.loads((O/'manuscript_pre_strengthening.json').read_text());supp=json.loads((O/'supplement_pre_strengthening.json').read_text())
TITLE='Gain constrained regression improves transcriptomic prediction across spaceflight and Earth brain datasets'
oldtitle=main[0]['text']
for b in main+supp:
 if 'text' in b:b['text']=b['text'].replace(oldtitle,TITLE)
def H(t,l=2):return dict(type='heading',text=t,level=l)
def P(t):return dict(type='paragraph',text=t)
def E(t):return dict(type='equation',text=t)
def idx(t):return next(i for i,b in enumerate(main) if b.get('text')==t)
def before(t,blocks):main[idx(t):idx(t)]=blocks
look=[]
def value(file,filters,field):
 d=pd.read_csv(R/file)
 for k,v in filters.items():d=d[d[k]==v]
 assert len(d)==1,(file,filters,len(d))
 v=float(d.iloc[0][field]);look.append(dict(source_file=file,filters=json.dumps(filters,sort_keys=True),field=field,value=v));return v
SF='extensions/strengthening_20261015/method_benchmark/strengthened_summary.csv'
def sv(a,f='mean_MSE_ratio',m='spectral_constrained_ridge_CV'):return value(SF,{'accession':a,'method':m},f)
BF='extensions/strengthening_20261015/biological_validation/all_biological_effects.csv'
bio=pd.read_csv(R/BF)
# Exact estimand labels are selected without effect-based filtering.
core=bio[(bio.accession=='OSD-562')&(bio.endpoint=='Circadian')&(bio.sensitivity=='all_animals')]


def bv(estimand,field,adjusted=False):return value(BF,dict(accession='OSD-562',endpoint='Circadian',sensitivity='all_animals',estimand=estimand,composition_adjusted=adjusted),field)
abstract=('Collection-associated signatures can be reproducible without supporting reliable genome-wide correction. We analysed seven NASA brain deposits and four external mouse-brain datasets, preserving animal and pooled-sample units. In 362 ground holdouts, multi-sensor ridge regression improved prediction but allowed substantial amplification. We formulated gain-constrained regression as a convex problem with verifiable optimality and stability bounds. With training-only preprocessing and nested selection, the gain-two estimator reduced mean held-out prediction error by 1.2–5.2% in the original settings and 1.4–7.2% across 64 external animal/pool holdouts. Established-method comparisons and 1,400 count simulations showed that improved prediction and bounded amplification do not establish biological recovery. Circadian and erythroid-associated effects remained context dependent, without corrected cross-context replication. These results provide an auditable approach to prediction under correction constraints and distinguish numerical stability from causal interpretation.')
assert len(abstract.split())<=150
main[idx('Abstract')+1]=P(abstract)
main[6]=P('Keywords: spaceflight; brain transcriptomics; constrained regression; correction stability; independent datasets; nested validation; reproducibility.')
main[13]=P('We investigated when a collection-associated sensor can support useful prediction beyond its constituent genes. The analysis first audits identity, inference and failure of original score subtraction, then compares ridge regression [30], principal-component regression and partial least squares [31] under identical held-out animals. A multi-sensor convex formulation places a spectral gain constraint inside the prediction objective [33,34]. Four additional design-selected deposits test the refitted algorithm outside the original resource, and known-truth count simulations compare it with established batch and control-gene methods [16,17,32]. The contribution is a validated stability-constrained analysis for these data, rather than a new claim of nuisance identifiability or a novel general optimization theorem.')
before('Ground collection cohorts share response programs with flight contrasts',[
 H('External datasets expand the available experimental contexts'),
 P('Four additional NASA deposits contributed 66 acquired count columns and 64 primary expression units (Table 5). OSD-202 contains 40 individual female mouse brains in a cobalt-57 radiation-by-hindlimb-unloading design sampled at one and four months. OSD-352 contributes six individual female BALB/c brains from RR-3, a mission distinct from the three original missions. OSD-374 contains eight disjoint two-animal male hippocampal pools after proton irradiation. OSD-611 contains twelve two-hippocampus pools after Si28 exposure, of which ten are listed in NASA’s SampleTable and form the primary analysis [35,36,37,38]. The two additional OSD-611 count columns are retained for biological sensitivity analysis; their omission from SampleTable is unexplained. The primary total is 46 individual-animal units and 18 pooled units, not 64 individual animals. All external datasets were chosen for accessible adult mouse-brain counts and interpretable exposure/control designs before their new analysis outcomes were examined.'),
 P('Earth irradiation, hindlimb unloading, post-exposure time and distinct brain anatomies are evaluated as separate contexts. They are not treated as biological replications of microgravity. RR-3 RNA integrity ranges are completely separated between flight (6.3–6.8) and ground (7.5–8.1); the primary flight contrast therefore cannot separate exposure from RNA-quality-associated effects. OSD-611 pool-member identities are unavailable, limiting identity-level overlap audits. External validation below concerns prediction after within-cohort refitting; it is not prospective validation of frozen coefficients across missions.')])
before('Real-data attenuation is heterogeneous and uncertain',[
 H('Constrained multi-sensor regression improves held-out prediction'),
 P('The same 362 original ground holdouts were reanalysed with ridge, principal-component and partial-least-squares predictors, a continuously selected scalar loading, and gain-two clipped ridge. Every predictor used the available inherited Sensor31 genes and training-only preprocessing. Ordinary ridge reduced mean outside-sensor MSE by 6.0%, 13.4% and 9.6% in OSD-561, OSD-562 and OSD-525, respectively, but mean correction gains were 28.8, 18.6 and 11.9. Predictive accuracy alone therefore did not provide a stability guarantee (Fig. 11).'),
 P('We next minimized regularized multi-output prediction loss subject to a spectral-norm constraint on the coefficient matrix. This produces a complete correction operator with gain at most two while annihilating the sensor coordinates (Methods). All 16,084 fitted optimization problems met the specified relative optimality-gap tolerance of 10⁻⁷. Twelve independently solved full-coefficient convex problems passed 96 checks, including objective agreement, feasibility, gain, idempotence and sensor annihilation.'),
 P(f'The constrained estimator had mean held-out MSE ratios {sv("OSD-561"):.4f}, {sv("OSD-562"):.4f} and {sv("OSD-525"):.4f} against the nuisance-only baseline in the three original settings, corresponding to reductions of {100*(1-sv("OSD-561")):.1f}%, {100*(1-sv("OSD-562")):.1f}% and {100*(1-sv("OSD-525")):.1f}%. It improved prediction in 78/81, 81/81 and 200/200 retained splits, respectively. These overlapping splits arise from 30 unique ground animals and do not provide 362 independent biological replicates or a valid independent-split significance test. Gain-two clipping and constrained loss minimization are distinct estimators; their initial comparisons also use different regularization grids, so those differences alone do not isolate the effect of the constraint formulation.'),
 H('The constrained algorithm generalizes to four external prediction settings'),
 P(f'Leaving out one complete individual animal or pool at a time gave mean MSE ratios {sv("OSD-202"):.4f}, {sv("OSD-352"):.4f}, {sv("OSD-374"):.4f} and {sv("OSD-611"):.4f} in OSD-202, OSD-352, OSD-374 and the ten primary OSD-611 pools, respectively (Fig. 12; Table 6). Prediction improved in 37/40, 5/6, 8/8 and 9/10 held-out units. Pooled squared-error ratios were {sv("OSD-202","pooled_SSE_ratio"):.4f}, {sv("OSD-352","pooled_SSE_ratio"):.4f}, {sv("OSD-374","pooled_SSE_ratio"):.4f} and {sv("OSD-611","pooled_SSE_ratio"):.4f}; these differ from equally weighted unit ratios because baseline errors vary. Every constrained operator retained gain at most two.'),
 P('The constrained algorithm was not universally the most accurate predictor. Unbounded ridge achieved a mean MSE ratio of 0.8028 in OSD-202, and the original unbounded score achieved 0.7344 in OSD-374. Constraining amplification trades some attainable prediction for a verifiable worst-direction bound. No external holdout was used to choose its own preprocessing reference or regularization parameter. The external cohorts extend algorithm evaluation beyond the original overlapping resource, while their small sizes and heterogeneous designs limit claims about any common biological mechanism.')])
before('Discussion',[
 H('Count simulations separate predictive restraint from biological recovery'),
 P('An additional complete benchmark generated 1,400 independent negative-binomial datasets calibrated to empirical count means and within-design dispersions from OSD-561. Seven fixed scenarios crossed two source-training sizes (8 and 24), with 100 repetitions per configuration and 14 correction/inference pipelines. All 19,600 method-by-dataset runs completed. Published ComBat was evaluated with and without empirical Bayes and with both simple and batch-aware downstream inference; RUVg matrix removal and control-factor covariate adjustment used known synthetic negative controls. PCA adjustment was labelled separately from surrogate-variable analysis (Fig. 13).'),
 P('Under weak transferable nuisance in these count scenarios, nested ridge and constrained ridge usually selected the no-prediction baseline for outside-sensor expression. Their outside-sensor biological-effect RMSE was consequently close to unadjusted analysis; this experiment does not demonstrate a general recovery advantage for the new constraint. With 24 training samples and changed loading, outside-sensor RMSE was 0.426 for constrained regression, 0.473 for bounded scalar correction and 0.513 for the original score. Oracle-control RUVg matrix correction reached 0.403 in that setting. These methods have different information: ground-derived estimators use only source controls, whereas target batch labels or known negative controls support the established comparators.'),
 P('Biological false discoveries depended strongly on both correction and downstream inference. In the strongly correlated scenario at training size 24, mean false discovery proportions were 0.125 for constrained regression, 0.037 for known-batch OLS, 0.632 for ComBat EB followed by simple inference and 0.137 for ComBat EB with the batch covariate retained. The nominal gene-wise BH target was 0.05. Such results support reporting inference after estimated correction rather than interpreting a clean expression matrix as calibrated uncertainty. All scenario results, including negative controls, power and failures, remain in complete electronic tables.'),
 H('Expanded robustness narrows the biological candidate interpretation'),
 P('A further exploratory family retained all eight inherited panels, seven fixed erythroid-associated markers and their fixed score, age-saturated contrasts, metadata exclusions, marker adjustment, external exposure contrasts and direction screens. Its 1,488 effect/screen rows contained 1,047 finite probabilities in one new BH/BY family. The full hippocampal additive-age Circadian interaction was −0.4053 log2 (95% animal-bootstrap interval −0.5967 to −0.2170; restricted wild p=0.000760; new BH q=0.03617). Adding the erythroid score changed the estimate to −0.3980, only 1.81% attenuation, but adjusted BH q=0.1150. The score explained 0.000523 of remaining panel residual variance conditional on the base design; this is not a cell-fraction or mediation estimate (Supplementary Fig. 6).'),
 P('The equal-age saturated Circadian contrast was −0.4085 (interval −0.6062 to −0.2146; p=0.001720; new BH q=0.05628). Both age-specific estimates and every identifiable single-animal or single-gene omission retained negative directions. No result in the new family passed BY correction. RR-3 Circadian expression showed a small opposite-direction flight estimate of 0.0226 (interval −0.1090 to 0.1756; p=0.84167), and no Earth panel/marker endpoint or harmonized common-direction panel screen passed the complete new BH family (Supplementary Fig. 7). The full effect’s weak dependence on this particular erythroid score strengthens its descriptive characterization; it does not establish independent replication or exclude other compositional mechanisms.')])
# Recast Discussion around the actual constructive result and its limits.
a=idx('Discussion');b=idx('Methods');main[a+1:b]=[
 P('The main contribution is an auditable way to obtain useful transcriptomic prediction under an explicit amplification constraint. A gain-two convex multi-sensor estimator improved mean held-out outside-sensor prediction in all three original settings and four external datasets. Its fitted objectives were certified numerically, and an independent full-coefficient solver verified the optimization and operator identities. This strengthens the methodological evidence beyond within-resource sensor discrimination, while keeping the distinction between numerical reliability and biological recovery explicit.'),
 P('Ordinary ridge often predicted better than constrained regression, particularly in the larger Earth experiment. Its large operator gains show why unconstrained prediction loss and safe subtraction answer different questions. The imposed gain bound controls the worst possible Euclidean amplification on the retained normalized gene coordinates; it does not promise lower error for every biological vector or account automatically for uncertainty in sensor measurement. Moreover, annihilating all sensor genes removes any genuine biology carried by those coordinates. The method is appropriate only when this removal is scientifically acceptable; prediction can otherwise be reported without applying it as biological correction.'),
 P('Spectral constraints, ridge regularization, singular-value projection and accelerated convex optimization are established tools [30,33,34]. The methodological advance here is their explicit coupling to a transcriptomic correction operator, exact response-row-space computation, verifiable optimality gaps, nested preprocessing and complete evaluation on heterogeneous spaceflight and Earth brain data. We do not claim priority for a general spectral-ball regression theorem. The previously demonstrated scalar-score geometry explains the failure mode; the multi-sensor constrained objective supplies a constructive, testable alternative.'),
 P('The external evaluation addresses a major limitation of relying only on the original overlapping animal resource. It includes a separate flight mission and three reported Earth exposure datasets with preserved animal or pooled-sample units. However, it validates a refitted algorithm within each new cohort. It does not show that coefficients learned on one mission transfer unchanged to another, nor that Earth perturbations reproduce microgravity. Unknown OSD-611 donor identities, small RR-3 groups, RNA-integrity separation, pooled hippocampi, technical lane structure and differing anatomy remain material design limits.'),
 P('The count benchmark further limits biological interpretation. When source nuisance did not predict target expression reliably, nested selection often chose no outside-sensor correction. Established control-gene methods sometimes had better effect RMSE, and known-batch regression was better calibrated in strongly confounded simulations. Post-ComBat batch adjustment reduced, but did not always eliminate, excess discoveries. The comparison therefore demonstrates an accuracy–stability–inference tradeoff rather than universal superiority. Generic negative-binomial mechanisms calibrated to marginal counts do not reproduce the full RNA-sequencing process, cell mixtures or all collection artifacts.'),
 P('The Circadian interaction remains a focused descriptive candidate. Its estimate persists across age specifications and changes little after the chosen erythroid-marker adjustment. Yet its inferential support depends on the model and multiplicity control; the separate RR-3 comparison and cross-context screens do not establish replication. Neither marker adjustment nor normalization identifies cell composition, contamination or causal regulation. Other inherited panel signals also share genes and biological functions, so panel labels do not constitute measured cell types, temporal trajectories or physiological injury.'),
 P('All analyses are exploratory secondary analyses of deposited processed counts. We did not re-align raw sequencing reads, randomize animals or determine sample size prospectively. Repeated holdouts, bootstrap samples, shared tissues and correlated sensitivity analyses add diagnostic information without adding animals. Future experiments should cross exposure with matched collection and preservation, include sufficient independent animals and appropriate ground analogues, and predefine biological contrasts and sensor use. Frozen-model transport and orthogonal physiological or cell-resolved validation would test claims that the present data cannot resolve.'),
 P('These results support a practical conclusion: stable prediction can be made constructive and auditable even when causal nuisance separation remains unidentified. The gain-constrained formulation provides measurable prediction gains with explicit mathematical limits; biological discovery requires an additional, independently supported line of evidence.')]
before('Statistics and reproducibility',[
 H('External cohort acquisition and experimental units'),
 P('External accessions OSD-202, OSD-352, OSD-374 and OSD-611 were selected from available NASA metadata for adult mouse brain bulk integer counts and an interpretable perturbation/control design [35,36,37,38]. Original raw processed matrices, metadata JSON, SampleTables and ISA archives are supplied with SHA-256 records. Counts-to-assay mapping determines experimental units. RR-3 bulk count columns already aggregate technical section libraries; their six animals were not collapsed again. OSD-374 pools have two explicit, nonoverlapping donor IDs each. OSD-611 collection protocols identify two-hippocampus pools but do not disclose donor IDs. Its primary mask follows NASA SampleTable membership (3 sham, 5 at 0.3 Gy and 2 at 0.6 Gy); all twelve deposited pools form a separately labelled biological sensitivity. Study protocols and unit membership are preserved in external_data/DATASET_PROTOCOL.md and acquisition tables.'),
 P('OSD-202 has a 0.04-Gy cobalt-57 radiation-by-unloading design with 21-day unloading and one/four-month sampling. All eight design cells are retained (minimum n=2). OSD-374 compares 1-Gy protons with sham, four pools each, two weeks later. OSD-611 compares 0.3/0.6-Gy Si28 with sham two weeks later. Sex, strain, age and collection timing differ across experiments. The external prediction baseline includes intercept, time and unloading for OSD-202 and an intercept for the other studies; biological inference uses each complete study-specific exposure design and its declared technical sensitivities.'),
 H('Nested multi-sensor prediction and comparison'),
 P('All original split roles are inherited from the 362 ground holdouts. Each external primary unit is held out once. For every outer and inner fit, canonical-gene mean-count filtering, positive-reference median-ratio normalization, nuisance coefficients and sensor RMS scaling are estimated exclusively from the training units. The same available Sensor31 coordinates predict all retained outside-sensor genes. Inner leave-one-training-unit-out squared error selects regularization or dimension, with deterministic ordering and a no-prediction baseline candidate. The ridge/clipped-ridge grid is baseline, 1000, 100, 10, 1, 0.1, 0.01 and 0.001; PCR and PLS2 use zero to four available components. A continuous scalar comparator minimizes inner residual risk on the interval zero to one while preserving the anchored sensor component. Existing grid-selected scalar and bounded-score methods are retained. The initial convex grid is baseline, 10, 1, 0.1 and 0.01. Different initial grids are disclosed rather than attributing their entire comparison to the optimizer.'),
 P('Means of split MSE ratios, pooled SSE ratios, all individual errors, operator gains and tuning choices are exported. Original overlapping splits are descriptive robustness evaluations and are not used as independent observations for a significance test. External test units are disjoint within each dataset, but their training sets overlap; no naive fold-based confidence interval is used. Hyperparameter selection and the exploratory extension protocol were fixed before these outer results were inspected. External expression fitting uses both exposure groups but never the held-out unit; improved predictability may include real exposure biology and is not labelled identified artifact removal.'),
 H('Gain constrained regression and exact operator geometry'),
 P('Let S be the n-by-p training sensor residual matrix, Y the n-by-q outside-sensor residual matrix, and D the diagonal matrix of positive training sensor RMS scales, replacing near-zero scales by one. Coefficients C are in raw normalized sensor units. For each nonbaseline regularization parameter α>0, solve the convex problem below, with L=2. The baseline C=0 is selected separately by inner validation. Ridge references [30] motivate the penalty; the spectral ball is a standard convex constraint [33].'),
 E('C* = argmin { ‖Y−SC‖F²/(2n) + α‖DC‖F²/2 : ‖C‖₂ ≤ √(L²−1) }.    (9)'),
 P('Write E_s=[I_p,0] for the sensor selector in sensor-first coordinates. Subtraction of the predicted outside-sensor component while zeroing sensor coordinates gives the block operator below. Its nonzero singular values are those of [−Cᵀ,Iq], so the largest is √(1+‖C‖₂²). Direct block multiplication gives idempotence and E_sA=0. These identities concern the retained normalized expression coordinates, conditional on fitted preprocessing.'),
 E('A = [0, 0; −Cᵀ, Iq];     A² = A;     E_sA = 0;     ‖A‖₂ = √(1+‖C‖₂²) ≤ L.    (10)'),
 P('For any biological vector b, Ab−b=−[I_p;Cᵀ]E_sb; the block multiplier has norm √(1+‖C‖₂²). Thus the bound below holds. Biology wholly outside the sensor coordinates is preserved by this algebra, while genuine biology inside them may be removed. For positive-semidefinite covariance Σ, λmax(AΣAᵀ)≤L²λmax(Σ), which allows fourfold directional variance at L=2 and does not imply variance contraction.'),
 E('‖Ab−b‖₂ ≤ L‖E_sb‖₂.    (11)'),
 P('Post-fit singular-value clipping is the nearest feasible coefficient matrix in Frobenius distance to an unconstrained coefficient matrix. It need not minimize the weighted regression objective in equation (9), whose Hessian depends on sensor covariance and scale. Convex optimization directly minimizes that objective over the same feasible set; for fixed α and preprocessing its training objective cannot exceed that of any feasible clipped comparator at exact optimality. This statement does not guarantee superior held-out prediction.'),
 H('Response-space computation and independent optimality verification'),
 P('Factor Y=U diag(s)Vᵀ on its nonzero response row space and write C=T Vᵀ. Components orthogonal to that row space cannot improve the linear fit and weakly increase the quadratic loss, ridge penalty and spectral norm. Optimization can therefore use the p-by-r matrix T, r≤n, without constructing the full p-by-q matrix in each iteration. The implementation retains eigenvalues of YYᵀ above 10⁻¹² times the larger of its maximum eigenvalue and one; discarded floating-point directions define its numerical rank. Set H=SᵀS/n+αD² and F=SᵀU diag(s)/n. The gradient is HT−F, and each step projects onto the spectral ball by singular-value clipping. Accelerated steps use a monotone objective restart and step size 1/λmax(H), following established proximal-gradient principles [34].'),
 P('The reported Frank–Wolfe gap uses the nuclear norm, dual to the spectral norm. It is an upper bound on objective suboptimality for the represented convex problem. Fits stop when the gap is at most 10⁻⁷ times max(1, the zero-coefficient objective), with at most 2,000 iterations. All 16,084 original/external inner and outer nonbaseline fits converged. Certificates, selected parameters, response ranks and training-unit identities are fully exported.'),
 E('gap(T) = ⟨∇f(T), T⟩ + √(L²−1)‖∇f(T)‖* ≥ f(T)−f(T*).    (12)'),
 P('An independent verifier solved twelve small full-coefficient problems with CVXPY/Clarabel using the block positive-semidefinite constraint [cI,C;Cᵀ,cI]≥0, c=√(L²−1). The maximum objective difference from the production response-space solver was 2.46×10⁻⁹. Ninety-six checks also independently reconstructed the loss, duality gap, feasibility and dense operator identities. An earlier SLSQP verification attempt failed to solve several nonsmooth spectral-boundary cases accurately; that diagnostic is retained, and its solver disagreement is not represented as a production result.'),
 H('Real count calibrated correction benchmark'),
 P('The supplementary count experiment follows a fixed seven-scenario, two-training-size protocol with seed 15102026561 and 100 independent datasets per configuration. Six hundred canonical genes with mean count at least 200 were sampled once from OSD-561. Gene-wise negative-binomial dispersions were moment estimates from residual variation within age-by-flight-by-collection groups, clipped to 0.02–0.5. Training counts have no biological contrast and n=8 or 24; target n=24 has balanced biological groups and recorded batch correlations 0, 0.5 or approximately 0.83. Thirty sensor genes, 120 known null controls and 60 nonsensor biological genes are fixed by index. Nonzero biological log2 coefficients are randomly ±0.8. Other scenarios reverse target nonsensor nuisance loadings, add genuine biology to eight sensor genes, double dispersion in one batch, or set all biological effects to zero. Count means include independent lognormal library factors. The truth is a log2 mean-count coefficient, so ordinary linear inference on log(count+1) is deliberately model-misspecified.'),
 P('The official neuroCombat 0.2.12 implementation [32] receives target batch and protected biological labels. We report EB and non-EB forms, each followed by either biology-only regression or biology-plus-batch regression. RUVg follows the published RUVSeq log-input matrix algorithm [16]: centered control-gene expression defines its first left singular vector W, and matrix adjustment subtracts WWᵀY. A distinct RUVg covariate version fits unadjusted expression on biology and W. Controls are oracle-known synthetic null genes; this information advantage is explicit. PCA uses the first target-expression component and is not described as SVA. Comparator source files and hashes are archived. Ground-only predictors use source counts and nested inner normalization references; no target labels select their correction parameters.'),
 P('Each method retains all 600 gene tests in its own within-dataset BH family. RMSE compares inferred effects with the known biological vector, with both all-gene and outside-sensor values reported. FDP is false discoveries divided by max(1,total discoveries); power uses true nonnull genes and remains unavailable in the all-null scenario. Scenario-specific means, independent-repetition distributions and Monte Carlo standard errors are exported, and paired method differences use the independently generated datasets. A version-one development run is retained; the documented version-two amendment corrected inner normalization refitting and added standard ridge, constrained regression and batch-aware post-ComBat inference without selecting scenarios, seeds or favorable outcomes.'),
 H('Expanded biological sensitivity and complete family control'),
 P('The new exploratory biological protocol fixes the eight inherited panels, individual erythroid-associated genes Hba-a1, Hba-a2, Hbb-bs, Hbb-bt, Alas2, Slc4a1 and Gypa, and their available-gene mean log-expression score before these results. It estimates original flight contrasts and flight-by-collection interactions, full age-by-flight-by-collection saturated contrasts, equal-age averages and age differences. A second version includes the fixed marker score as a covariate. This is descriptive adjustment for a chosen expression signature, not validated deconvolution or mediation. Every identifiable single-animal and single-gene omission is exported as a dependence diagnostic; singular designs retain unavailable estimates or uncertainty.'),
 P('External models respect study-specific exposure, dose, unloading and collection-time factors. They retain OSD-202 lane-adjusted sensitivities, RR-3 RIN adjustment and all-twelve-pool OSD-611 sensitivities. Unit leverage of one, residual degrees of freedom or rank failures lead to unavailable uncertainty rather than imputation. Same-anatomy flight screens use common retained panel genes, consistent direction and the maximum component p value. Cross-context differences and all component effects are retained; nonexchangeable Earth and flight exposures are not combined into a causal meta-analysis.'),
 P('The new inferential engine uses HC3 studentization with 99,999 restricted-null wild sign draws, whole-unit stratified percentile bootstraps with 2,000 draws and fixed seed 20261015561562. These resamples hold the normalized expression matrix fixed, so intervals condition on preprocessing rather than propagating re-estimation of normalization references. Technical regions of the same animal are never resampled as independent animals. All 1,047 finite probabilities among 1,488 effect/screen rows enter one complete new BH/BY family; this exploratory family is separate from the earlier primary, exact-label, paired and interaction families. Thirty correlated rows pass BH and none passes BY; these rows are not thirty independent discoveries. An independent verifier passed 1,337 checks including source-count normalization, dense-regression contrasts, HC3 sandwiches, independent restricted-null draws, SciPy BH/BY and source hashes.')])
